use crate::aap::caps::kb_read;

struct Node;

/// Upper bound on the question length, in characters (Unicode scalar values),
/// matching the Python-side `len(question) <= 512`.
const MAX_QUESTION_CHARS: usize = 512;

/// Returns `s` unchanged if it is within the bound, otherwise the first
/// `MAX_QUESTION_CHARS` characters. Truncating on char boundaries keeps the
/// result valid UTF-8.
fn bound_question(s: String) -> String {
    if s.chars().count() <= MAX_QUESTION_CHARS {
        s
    } else {
        s.chars().take(MAX_QUESTION_CHARS).collect()
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        // `Intent` is `Copy`, so this does not move out of `query`.
        let intent = query.query.intent;

        // `requires` already guarantees the bound; enforcing it here keeps the
        // `ensures` clause true of every output, not only of well-formed inputs.
        let question = bound_question(query.query.question);

        // The node's only authority is the read-only knowledge base.
        let mut knowledge = kb_read::lookup(&question);

        // `ensures present(knowledge)`: the field must be populated. If the
        // store has nothing for this question, emit an explicit marker rather
        // than an empty list.
        if knowledge.is_empty() {
            knowledge.push(String::from("no knowledge found for this question"));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
